const json = xml2Json(pm.response.text());
const transactions = json.transactions.transaction;
const txArray = Array.isArray(transactions) ? transactions : [transactions];

// 1. Status code is 200
pm.test("Status code is 200", () => {
    pm.response.to.have.status(200);
});

// 2. Response time is under 5000ms
pm.test("Response time is acceptable", () => {
    pm.expect(pm.response.responseTime).to.be.below(5000);
});

// 3. Response is XML with transactions
pm.test("Response is XML with transactions", () => {
    pm.expect(pm.response.text()).to.include("<transactions>");
    pm.expect(txArray.length).to.be.above(0);
});

// 4. Each transaction has required fields
pm.test("Each transaction has the expected fields", () => {
    txArray.forEach(tx => {
        pm.expect(tx).to.include.keys("id", "accountId", "type", "date", "amount", "description");
    });
});

// 5. Transaction type is valid (Debit or Credit)
pm.test("Transaction types are Debit or Credit", () => {
    txArray.forEach(tx => {
        pm.expect(["Debit", "Credit"]).to.include(tx.type);
    });
});

// 6. Transaction amount is a positive number
pm.test("Transaction amounts are positive numbers", () => {
    txArray.forEach(tx => {
        pm.expect(parseFloat(tx.amount)).to.be.above(0);
    });
});

// 7. Transaction accountId matches the collection variable account_id
pm.test("All transactions belong to the requested account", () => {
    const accountId = pm.collectionVariables.get("account_id");
    txArray.forEach(tx => {
        pm.expect(tx.accountId).to.equal(accountId);
    });
});

